        break;
    case 1:
        sTVShowState = 2;
        break;
    case 2:
        if (!gSaveBlock1Ptr->gabbyAndTyData.battleTookMoreThanOneTurn)
            sTVShowState = 4;
        else if (gSaveBlock1Ptr->gabbyAndTyData.playerThrewABall)
            sTVShowState = 5;
        else if (gSaveBlock1Ptr->gabbyAndTyData.playerUsedHealingItem)
            sTVShowState = 6;
        else if (gSaveBlock1Ptr->gabbyAndTyData.playerLostAMon)
            sTVShowState = 7;
        else
            sTVShowState = 3;
        break;
    case 3:
        StringCopy(gStringVar1, gSpeciesNames[gSaveBlock1Ptr->gabbyAndTyData.mon1]);
        StringCopy(gStringVar2, gMoveNames[gSaveBlock1Ptr->gabbyAndTyData.lastMove]);
        StringCopy(gStringVar3, gSpeciesNames[gSaveBlock1Ptr->gabbyAndTyData.mon2]);
        sTVShowState = 8;
        break;
    case 4:
    case 5:
    case 6:
    case 7:
        sTVShowState = 8;
        break;
    case 8:
        CopyEasyChatWord(gStringVar1, gSaveBlock1Ptr->gabbyAndTyData.quote[0]);
        StringCopy(gStringVar2, gSpeciesNames[gSaveBlock1Ptr->gabbyAndTyData.mon1]);
        StringCopy(gStringVar3, gSpeciesNames[gSaveBlock1Ptr->gabbyAndTyData.mon2]);
        gSpecialVar_Result = TRUE;
        sTVShowState = 0;
        TakeGabbyAndTyOffTheAir();
        break;
    }
    ShowFieldMessage(sTVInSearchOfTrainersTextGroup[state]);

TryBecomeLinkLeader.body:
u8 taskId;
    struct WirelessLink_Leader *data;

    taskId = CreateTask(Task_TryBecomeLinkLeader, 0);
    sWirelessLinkMain.leader = data = (void *)(gTasks[taskId].data);
    sLeader = data;

    data->state = LL_STATE_INIT;
    data->textState = 0;
    gSpecialVar_Result = LINKUP_ONGOING;

TryJoinLinkGroup.body:
u8 taskId;
    struct WirelessLink_Group *data;

    taskId = CreateTask(Task_TryJoinLinkGroup, 0);
    sWirelessLinkMain.group = data = (void *)(gTasks[taskId].data);
    sGroup = data;

    data->state = LG_STATE_INIT;
    data->textState = 0;
    gSpecialVar_Result = LINKUP_ONGOING;

RunUnionRoom.body:
struct WirelessLink_URoom *uroom;

    ResetHostRfuGameData();
    CreateTask(Task_RunUnionRoom, 10);


    sWirelessLinkMain.uRoom = sWirelessLinkMain.uRoom;

    uroom = AllocZeroed(sizeof(*sWirelessLinkMain.uRoom));
    sWirelessLinkMain.uRoom = uroom;
    sURoom = uroom;

    uroom->state = UR_STATE_INIT;
    uroom->textState = 0;
    uroom->unknown = 0;
    uroom->unreadPlayerId = 0;

    gSpecialVar_Result = 0;
    ListMenuLoadStdPalAt(BG_PLTT_ID(13), 1);

InitUnionRoom.body:
struct WirelessLink_URoom *data;

    sUnionRoomPlayerName[0] = EOS;
    CreateTask(Task_InitUnionRoom, 0);
    sWirelessLinkMain.uRoom = sWirelessLinkMain.uRoom;  
    sWirelessLinkMain.uRoom = data = AllocZeroed(sizeof(struct WirelessLink_URoom));
    sURoom = sWirelessLinkMain.uRoom;
    data->state = 0;
    data->textState = 0;
    data->unknown = 0;
    data->unreadPlayerId = 0;
    sUnionRoomPlayerName[0] = EOS;

TryBufferWaldaPhrase.body:
if (IsWaldaPhraseEmpty())
        return FALSE;

    StringCopy(gStringVar1, GetWaldaPhrasePtr());
    return TRUE;

TryGetWallpaperWithWaldaPhrase.body:
u16 backgroundClr, foregroundClr;
    u8 patternId, iconId;
    u16 trainerId = GetTrainerId(gSaveBlock2Ptr->playerTrainerId);
    gSpecialVar_Result = TryCalculateWallpaper(&backgroundClr, &foregroundClr, &iconId, &patternId, trainerId, GetWaldaPhrasePtr());

    if (gSpecialVar_Result)
    {
        SetWaldaWallpaperPatternId(patternId);
        SetWaldaWallpaperIconId(iconId);
        SetWaldaWallpaperColors(backgroundClr, foregroundClr);
    }

    SetWaldaWallpaperLockedOrUnlocked(gSpecialVar_Result);
    return (bool8)gSpecialVar_Result;

RockSmashWildEncounter.body:
u16 headerId = GetCurrentMapWildMonHeaderId();

    if (headerId != HEADER_NONE)
    {
        const struct WildPokemonInfo *wildPokemonInfo = gWildMonHeaders[headerId].rockSmashMonsInfo;

        if (wildPokemonInfo == NULL)
        {
            gSpecialVar_Result = FALSE;
        }
        else if (WildEncounterCheck(wildPokemonInfo->encounterRate, TRUE) == TRUE
         && TryGenerateWildMon(wildPokemonInfo, WILD_AREA_ROCKS, WILD_CHECK_REPEL | WILD_CHECK_KEEN_EYE) == TRUE)
        {
            BattleSetup_StartWildBattle();
            gSpecialVar_Result = TRUE;
        }
        else
        {
            gSpecialVar_Result = FALSE;
        }
    }
    else
    {
        gSpecialVar_Result = FALSE;
    }

WonderNews_GetRewardInfo.body:
u16 *result = &gSpecialVar_Result;
    struct WonderNewsMetadata *data = GetSavedWonderNewsMetadata();
    u16 rewardType;


    if (!IsMysteryEventEnabled() || !ValidateSavedWonderNews())
        return NEWS_REWARD_NONE;

    rewardType = GetRewardType(data);

    switch (rewardType)
    {
    case NEWS_REWARD_RECV_SMALL:
    case NEWS_REWARD_RECV_BIG:
        *result = GetRewardItem(data);
        break;
    case NEWS_REWARD_SENT_SMALL:
        *result = GetRewardItem(data);
        IncrementSentRewardCounter(data);
        break;
    case NEWS_REWARD_SENT_BIG:
        *result = GetRewardItem(data);
        ResetSentRewardCounter(data);
        break;
    case NEWS_REWARD_NONE:
    case NEWS_REWARD_WAITING:
    case NEWS_REWARD_AT_MAX:
        break;
    }

    return rewardType;
